import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates by mean difference and t-test
    strong_candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            continue  # Skip clinical features for now
        mean_diff = np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])
        t_stat, _ = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i], equal_var=False)
        strong_candidates.append((fid, abs(mean_diff), abs(t_stat)))

    # Sort by t-statistic
    strong_candidates.sort(key=lambda x: x[2], reverse=True)

    # Remove near-duplicates based on correlation
    selected_features = []
    excluded = set()
    for fid, _, _ in strong_candidates:
        if fid in excluded:
            continue
        selected_features.append(fid)
        # Mark correlated features as excluded
        for other_fid, _, _ in strong_candidates:
            if other_fid != fid and other_fid not in excluded:
                col1 = feats.column(fid)
                col2 = feats.column(other_fid)
                corr = np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0, 1]
                if abs(corr) >= 0.6:
                    excluded.add(other_fid)
        if len(selected_features) >= MAX_DRIVERS:
            break

    # If no clear drivers, return empty design
    if not selected_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Try to find interactions among top features
    top_features = selected_features[:3]
    products = []
    for i in range(len(top_features)):
        for j in range(i+1, len(top_features)):
            fid1, fid2 = top_features[i], top_features[j]
            products.append((fid1, fid2))

    # Return the design with at most 4 drivers
    final_drivers = tuple(selected_features[:4])
    return Design(
        drivers=final_drivers,
        columns=tuple(selected_features),
        products=tuple(products),
        loadings={fid: 1.0 for fid in selected_features}
    )

